func makeFibonacci() -> (Int) -> Int {
    var memo: [Int: Int] = [:]
    func fib(_ n: Int) -> Int {
        if n <= 1 { return n }
        if let cached = memo[n] { return cached }
        let result = fib(n - 1) + fib(n - 2)
        memo[n] = result
        return result
    }
    return fib
}
